@spec tv_fx_region_spec  src=tests/specs/tv_fx_region_spec.lua  loc=1551  cases=77
@exercises dataStore (h.ds), trackerManager (h.tm), midiManager (h.fm), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr), clipboard (h.clipboard)
@surface   ds:assign, tm:rebuild, tm:addEvent, tm:flush, ds:get, fm:dump, vm:setGridSize, vm:ppqToRow, ec:setPos, vm:fxHostForEdit, vm:noteFx, vm:setNoteFx, vm:removeFxStage, vm:addFxStage, vm:setFxField, ec:setSelection, vm:rowToPPQ, vm:fxHostAtCursor, cmgr:invoke, tm:getChannel, vm:editEvent, tm:subscribe, ec:row, ec:extendTo, clipboard:collect, vm:ghostOverlay, vm:noteLabel, vm:noteDeviation, vm:reserveGhostReadout, tm:assignEvent, vm:addExtraCol
@harness   mk{seed.ccs}

# Intent
  Track B (note macros v2): the fx-region column + Super-X addressing. A region
  renders as a tailed kind-badge in a per-channel fx column, and the v1 note-FX
  editor addresses it by uuid. see docs/trackerView.md § Addressing a chain

# Helpers
  @fn injectRegion(h, over)  @ 28-33
  @fn injectRegions(h, list)  @ 37-46
      -- Two producers, so a scoping case can ask which of them a ghost belongs to. Each entry
      -- overrides the defaults injectRegion uses; the uuid is positional ('fxr-1', 'fxr-2', ...).
  @fn noteAt(h, chan, ppq, pitch)  @ 48-52
  @fn fxColFor(h, chan)  @ 54-58
  @fn region(h, uuid)  @ 60-64
  @fn noteColIdx(h, chan, lane)  @ 66-70
  @fn ctsColIdx(h, chan, type, cc)  @ 72-76
  @fn addNote(h)  @ 78-82
  @fn authoredUuid(h)  @ 84-86
  @fn authoredPitches(h)  @ 90-97
      -- Pitches still sounding on the take (non-derived). Empty once a replace region has
      -- parked the covered chord off-take.

# Cases
  @case 'a region materialises a per-channel fx column with a badge + tail'  [harness]  @ 104-116
  @case 'a chain stacks its glyphs down the region rows in series order'  [harness]  @ 120-133
  @case 'a bypassed stage carries its flag down the stack'  [harness]  @ 137-147
  @case 'a chain longer than the region clips at the last row and marks it'  [harness]  @ 151-161
  @case 'a one-row region gives the clip mark the badge row'  [harness]  @ 165-173
  @case 'no region -> no fx column'  [harness]  @ 177-183
  @case 'an empty-fx region renders no column (it is an inert husk)'  [harness]  @ 187-193
  @case 'two overlapping regions pack into separate fx columns, each addressable'  [harness]  @ 199-227
  @case 'two disjoint regions share one fx column (packed into lane 1)'  [harness]  @ 231-243
  @case 'replace region: a parked note still renders in its note column'  [harness]  @ 249-261
  @case 'replace region: a parked cc still renders in its cc column'  [harness]  @ 265-288
  @case 'noteFx resolves a region uuid to its fx list'  [harness]  @ 294-299
  @case 'setNoteFx writes a region fx list back to ds'  [harness]  @ 303-309
  @case 'setNoteFx REMOVE deletes the region (a region is its fx)'  [harness]  @ 313-319
  @case 'region fx: deselecting the last kind keeps a husk the editor can repopulate'  [harness]  @ 323-333
  @case 'setFxField edits one region fx field, leaving the region'  [harness]  @ 337-343
  @case 'fxHostForEdit: caret on an fx cell returns the region uuid'  [harness]  @ 349-357
  @case 'fxHostForEdit: a selection mints a replace region over its span'  [harness]  @ 361-375
  @case 'fxHostAtCursor: a selection does not mint -- cursor movement has no side effect'  [harness]  @ 379-387
  @case 'fxHostAtCursor: caret anywhere in an fx region returns its uuid, nil past the tail'  [harness]  @ 391-404
  @case 'fxHostForEdit: off a note with no selection is nil; on a note, its uuid (v1)'  [harness]  @ 408-418
  @case 'parked note: a pitch nudge edits the off-take stash and re-renders, still parked'  [harness]  @ 424-438
  @case 'parked note: delete removes it from the stash and does not restore it when the window moves off'  [harness]  @ 442-453
  @case 'parked add: typing a note into a replace window stashes a logical spec, off the take'  [harness]  @ 457-471
  @case 'parked move-out: nudging a parked note past the window end restores it to the take'  [harness]  @ 475-488
  @case 'parked cc: a value nudge edits the off-take cc stash; delete removes it'  [harness]  @ 492-524
  @case 'parked pb: a value nudge edits the off-take pb stash; delete removes it'  [harness]  @ 528-564
  @case 'multi-select spanning a parked note and a take note: both edit under one rebuild'  [harness]  @ 568-589
  @case 'fx noteOff truncates the region tail to the cursor row'  [harness]  @ 595-607
  @case 'fx noteOff finds the right region in its lane when cells are in storage, not ppq, order'  [harness]  @ 611-625
  @case 'fx noteOff past the region tail grows it to the cursor row'  [harness]  @ 629-638
  @case 'fx noteOff on the onset row is a no-op (deletion is the delete verb, not noteOff)'  [harness]  @ 642-653
  @case 'fx noteOff on the window end row re-opens it to the pattern length'  [harness]  @ 657-667
  @case 'fx growNote / shrinkNote resize the region from its end'  [harness]  @ 671-682
  @case 'fx nudgeForward shifts the whole window and the caret follows'  [harness]  @ 686-698
  @case 'fx nudge keeps the moved region in its lane; the newly-overlapped sibling displaces right'  [harness]  @ 702-724
  @case 'fx nudge of an already-overlapping region keeps its own higher lane (no reorder)'  [harness]  @ 728-747
  @case 'fx nudge that makes an overlap disjoint tracks the caret across the column merge'  [harness]  @ 751-771
  @case 'fx window edit on a disjoint region does not churn storage order'  [harness]  @ 775-791
  @case 'fx nudgeBack refuses at the top grid edge (window unchanged)'  [harness]  @ 795-806
  @case 'fx eventShiftLeft swaps the region one lane left, flipping storage precedence'  [harness]  @ 812-836
  @case 'fx eventShiftRight swaps the region one lane right (the inverse move)'  [harness]  @ 840-855
  @case 'fx eventShift is a no-op at the grid edge (lone region, nothing beside it)'  [harness]  @ 859-871
  @case 'fx eventShift no-ops when the adjacent lane is empty at the cursor row'  [harness]  @ 875-890
  @case 'parked note: noteOff shortens its tail in the stash, stays parked'  [harness]  @ 896-909
  @case 'parked note: a time nudge within the window retimes the stash, stays parked'  [harness]  @ 913-926
  @case 'fx copy captures a region by onset; the whole window rides, tail spilling past the band'  [harness]  @ 932-950
  @case 'fx copy skips a region that only passes through the band (onset above it)'  [harness]  @ 954-963
  @case 'fx copy + paste stacks a duplicate region at the cursor row, original intact'  [harness]  @ 967-987
  @case 'fx delete removes the region under the caret'  [harness]  @ 991-1000
  @case 'fx deleteSel drops every region the rectangle catches (onset in band), sparing the rest'  [harness]  @ 1004-1021
  @case 'fx freeze promotes the region output to authored notes and drops the region'  [harness]  @ 1027-1039
  @case 'fx freeze converts an fx-carrying note at the caret'  [harness]  @ 1043-1055
  @case 'fx freeze declines on a plain note (no chain to freeze)'  [harness]  @ 1059-1069
  @case 'fx freeze: a refused freeze opens no undo block; an eligible one opens exactly one'  [harness]  @ 1076-1113
  @case 'ghostOverlay: no host under the caret returns nil, before any window query'  [harness]  @ 1119-1127
  @case 'ghostOverlay: a host lights its derived onsets on the lane column, with pitch and vel'  [harness]  @ 1131-1157
  @case 'ghostOverlay: a derived note is named from the step its own intent stands on'  [harness]  @ 1161-1179
  @case 'a lane pops the readout column open for an off-step ghost, and closes it after'  [harness]  @ 1183-1204
  @case 'ghostOverlay: a host whose onsets lie outside the window answers empty, not nil'  [harness]  @ 1208-1220
  @case 'ghostOverlay: a row carrying a real cell still reports its ghost -- precedence is the draw arm\'s'  [harness]  @ 1224-1237
  @case 'ghostOverlay: the window is the viewport -- onsets below it are absent'  [harness]  @ 1241-1257
  @case 'ghostOverlay: a derived lane the channel does not carry shows nothing'  [harness]  @ 1262-1276
  @case 'ghostOverlay: the lanes the user authored take the rest of the voices'  [harness]  @ 1280-1295
  @case 'ghostOverlay: a pb chain lights its curve on the column the channel carries'  [harness]  @ 1301-1319
  @case 'ghostOverlay: only the claimed target lights -- an authored cc beside it stays dark'  [harness]  @ 1323-1336
