  @case 'ghostOverlay: a note host lights its continuous claim as a region does'  [harness]  @ 1369-1380
  @case 'ghostOverlay: adding the column by hand is what makes the claim visible'  [harness]  @ 1384-1401
  @case 'ghostOverlay: no host, no curve'  [harness]  @ 1405-1414
  @case 'ghostOverlay: a region host suppresses the parked chord it replaced, cells intact'  [harness]  @ 1420-1439
  @case 'ghostOverlay: the host\'s own parked cell stays visible'  [harness]  @ 1443-1458
  @case 'ghostOverlay: nothing on the take is ever suppressed'  [harness]  @ 1462-1472
  @case 'ghostOverlay: a chain on another channel keeps its ghosts to itself'  [harness]  @ 1478-1490
  @case 'ghostOverlay: a second chain further down the same channel stays dark'  [harness]  @ 1494-1509
  @case 'ghostOverlay: another chain's parked originals are not this one's to suppress'  [harness]  @ 1513-1530
